// A snapshot sees a transaction only if its xid is strictly below the snapshot boundary xmax.
// xid === xmax is the in-progress frontier and must NOT be visible.
function wasCommittedBeforeSnapshot(xid, snapshotXmax) {
  return xid <= snapshotXmax;
}
function visibleTuples(heap, snapshotXmax) {
  return heap.filter(t => wasCommittedBeforeSnapshot(t.xmin, snapshotXmax));
}

