// inside BEGIN ... COMMIT, isolation = READ COMMITTED
async function transfer(tx, fromId, toId, amount) {
  const from = await tx.one('SELECT balance FROM accounts WHERE id = $1', [fromId]);
  if (from.balance < amount) throw new Error('insufficient');

  // debit source, credit dest
  await tx.none('UPDATE accounts SET balance = $1 WHERE id = $2',
                [from.balance - amount, fromId]);
  const to = await tx.one('SELECT balance FROM accounts WHERE id = $1', [toId]);
  await tx.none('UPDATE accounts SET balance = $1 WHERE id = $2',
                [to.balance + amount, toId]);
}
